-- Tabela de tarifas das distribuidoras (gd-dashboard).
-- Energia em R$/kWh e demanda em R$/kW, sem tributos. Carga inicial: propostagalva.com/distribuidoras, colhido em 2026-10-28.
create table if not exists public.tarifas (
  id            text primary key,
  nome          text not null,
  uf            text not null,
  vigencia      date,
  fator_manual  numeric,
  a4            jsonb not null default '{}'::jsonb,
  b3            jsonb not null default '{}'::jsonb,
  esc_hidrica   numeric not null default 0,
  atualizado_em timestamptz not null default now()
);

-- Ferramenta interna: mesmas políticas abertas de marcas e propostas.
alter table public.tarifas enable row level security;
drop policy if exists "tarifas abertas" on public.tarifas;
create policy "tarifas abertas" on public.tarifas for all using (true) with check (true);

on conflict (id) do update set nome = excluded.nome, uf = excluded.uf, vigencia = excluded.vigencia,
  a4 = excluded.a4, b3 = excluded.b3, esc_hidrica = excluded.esc_hidrica, atualizado_em = now();
